def build():
    atlas=Image.new('RGBA',(256,128));actors=Image.new('RGBA',(200,280))
    for i,k in enumerate(IDS): atlas.paste(relic(k),(i%8*32,i//8*32))
    for i in range(25): actors.paste(npc(i),(i%5*40,i//5*56))
    atlas.save(ROOT/'assets/relics-pixel-v09.png');actors.save(ROOT/'assets/npcs-v091.png')
    qa=ROOT/'qa/v091';qa.mkdir(parents=True,exist_ok=True)
    sheet=Image.new('RGB',(960,720),'#211B2C');d=ImageDraw.Draw(sheet)
    for i,k in enumerate(IDS):
        x,y=i%8*120,i//8*132;sheet.paste(relic(k).resize((96,96),Image.Resampling.NEAREST),(x+12,y),relic(k).resize((96,96),Image.Resampling.NEAREST));d.text((x+8,y+98),k,fill='#E5D5AD')
    sheet.save(qa/'relic-contact.png');actors.resize((600,840),Image.Resampling.NEAREST).save(qa/'npc-contact.png')
    fingerprints=[relic(k).tobytes() for k in IDS];assert len(set(fingerprints))==32
    assert len({npc(i).tobytes() for i in range(25)})==25
    assert set(atlas.getchannel('A').getdata()) == {0,255}
    (qa/'art-report.json').write_text(json.dumps({'relics':32,'npc':25,'uniqueSilhouettes':len({relic(k).getchannel('A').tobytes() for k in IDS}),'binaryAlpha':True}),encoding='utf8')
    print('Built 32 distinct relics and 25 NPC drawings; contact sheets in qa/v091.')

if __name__=='__main__': build()
